interface Shape { double area(); }
class Sq implements Shape {
  final double a;
  Sq(double a) { this.a = a; }
  public double area() { return a * a; }
}
class Main {
  public static void main(String[] args) {
    Shape s = new Sq(3);
    System.out.println(s.area());
  }
}

